const raw = JSON.parse($input.item.json.stdout);
const play = raw.plays[0];

let orchestratorTask = null;
for (const t of play.tasks) {
  const hostResult = t.hosts['homelab-node'];
  if (hostResult && hostResult.action === 'command') {
    orchestratorTask = hostResult;
    break;
  }
}

if (!orchestratorTask) {
  throw new Error('Could not find the polaris-backup command task in Ansible JSON output.');
}

const rc = orchestratorTask.rc;
const stdout = orchestratorTask.stdout || '';

// rc 5 = lock already held by another run - not a failure, nothing to classify
if (rc === 5) {
  return [{ json: { skipped: true, reason: 'lock_held' } }];
}

const collectors = {
  proxmox:    { display: 'Proxmox',  unchanged: 'Proxmox configuration is unchanged.' },
  pfsense:    { display: 'pfSense',  unchanged: 'pfSense configuration is unchanged.' },
  opnsense:   { display: 'OPNSense', unchanged: 'OPNSense configuration is unchanged.' },
  docker:     { display: 'Docker01', unchanged: 'Docker01 configuration is unchanged.' },
  admin01:    { display: 'Admin01',  unchanged: 'Admin01 configuration is unchanged.' },
  'admin-ws': { display: 'Admin-WS', unchanged: 'Admin-WS configuration is unchanged.' },
  switch:     { display: 'Switch',   unchanged: 'Switch configuration is unchanged.' },
};

const results = [];
for (const [id, info] of Object.entries(collectors)) {
  const failed = stdout.includes(`[ERROR] [${id}]`);
  const succeeded = stdout.includes(`[SUCCESS] ${info.display} collector completed successfully.`);
  const unchanged = stdout.includes(info.unchanged);

let status;
if (failed) status = 'failed';
else if (unchanged) status = 'unchanged';
else if (succeeded) status = 'changed';
else status = 'unknown';

  results.push({ collector: id, status });
}

return [{ json: { rc, results } }];

const vmidMap = {
  pfsense: 101,
  docker: 103,
  admin01: 105,
  'admin-ws': 201,
};

const { rc, results } = $input.all()[0].json;

const needsCheck = results
  .filter(r => r.status === 'failed' && vmidMap[r.collector] !== undefined)
  .map(r => ({ collector: r.collector, vmid: vmidMap[r.collector] }));

return needsCheck.map(item => ({ json: item }));

const classification = $('Classification').all()[0].json;
const allResults = classification.results;

let checkedList = [];
try { checkedList = $('Power-State').all(); } catch (e) { checkedList = []; }

let powerStatuses = [];
try { powerStatuses = $('NTFY \"Digest\"').all(); } catch (e) { powerStatuses = []; }

const poweredOff = {};
checkedList.forEach((item, i) => {
  const collector = item.json.collector;
  const status = powerStatuses[i]?.json?.data?.status;
  poweredOff[collector] = (status !== undefined && status !== 'running');
});

const tierTable = {
  proxmox:    { failure: true,  change: false },
  pfsense:    { failure: true,  change: true },
  opnsense:   { failure: true,  change: false },
  docker:     { failure: false, change: false },
  admin01:    { failure: true,  change: false },
  'admin-ws': { failure: false, change: false },
  switch:     { failure: false, change: false },
};

const output = [];

for (const r of allResults) {
  const tier = tierTable[r.collector] || { failure: false, change: false };

  if (r.status === 'failed') {
    const wasChecked = (r.collector in poweredOff);
    const isPoweredOff = poweredOff[r.collector] === true;
    if (wasChecked && isPoweredOff) continue; // Tier 0 - silent

    const cannotCheck = !wasChecked;
    output.push({
      collector: r.collector,
      reason: 'failed',
      urgency: (tier.failure || cannotCheck) ? 'urgent' : 'digest',
    });
  } else if (r.status === 'changed' && tier.change) {
    output.push({ collector: r.collector, reason: 'config_changed', urgency: 'urgent' });
  }
}

return output.map(o => ({ json: o }));

const items = $input.all().filter(i => i.json.urgency === 'digest');
if (items.length === 0) return [];

const lines = items.map(i => `- ${i.json.collector}: ${i.json.reason}`);
const message = `Routine items from today's backup run:\n${lines.join('\n')}`;

return [{ json: { message } }];
